inline std::string hexkey(Key x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) { s[i] = d[(unsigned)(x & 15)]; x >>= 4; }
    return s;
}
inline Key key(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    Key v = 0;
    for (char c : s) {
        int n = (c >= '0' && c <= '9') ? c - '0'
              : (c >= 'a' && c <= 'f') ? c - 'a' + 10
              : (c >= 'A' && c <= 'F') ? c - 'A' + 10 : -1;
        if (n < 0) throw std::runtime_error("key digit");
        v = (v << 4) | (unsigned)n;
    }
    return v;
}

